package vn.iotstar.controller; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.GetMapping; import vn.iotstar.service.*; @Controller @RequiredArgsConstructor public class HomeController{private final UserService users;private final ProductService products;@GetMapping("/")public String home(Model m){m.addAttribute("userCount",users.countUsers());m.addAttribute("productCount",products.countProducts());return "home";}}